import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_pipeline.h>

namespace {

constexpr int BM = 256;  // Double the CTA tile over the huge output row dimension to raise A/B reuse per CTA.
constexpr int BN = 64;   // Keep the small-K GEMM skinny in N per CTA.
constexpr int TK = 32;   // This workload has inner dimension K = 32.
constexpr int TM = 8;    // More row reuse per thread to cut B refetches.
constexpr int TN = 4;

__global__ void matmul_m32768_k32_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    const int rows,
    const int cols
) {
    __shared__ float As[BM][TK + 4];
    __shared__ float Bs[TK][BN + 4];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * blockDim.x + tx;
    const int nthreads = blockDim.x * blockDim.y;
    const int block_row = blockIdx.y * BM;
    const int block_col = blockIdx.x * BN;
    // Vectorized staging: K=32 and BN=64 are divisible by 4, so A and B tiles
    // can be cooperatively copied with float4 transactions.
    constexpr int A_VECS_PER_ROW = TK / 4;   // 8
    constexpr int B_VECS_PER_ROW = BN / 4;   // 16
    constexpr int A_VECS = BM * A_VECS_PER_ROW;  // 512
    constexpr int B_VECS = TK * B_VECS_PER_ROW;  // 512
    for (int idx = tid; idx < A_VECS; idx += nthreads) {
        const int r = idx / A_VECS_PER_ROW;
        const int c = (idx % A_VECS_PER_ROW) * 4;
        const int gr = block_row + r;
        if (gr < rows) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            __pipeline_memcpy_async(&As[r][c], A + gr * TK + c, sizeof(float4));
#else
            const float4 v = *reinterpret_cast<const float4*>(A + gr * TK + c);
            As[r][c + 0] = v.x;
            As[r][c + 1] = v.y;
            As[r][c + 2] = v.z;
            As[r][c + 3] = v.w;
#endif
        } else {
            As[r][c + 0] = 0.0f;
            As[r][c + 1] = 0.0f;
            As[r][c + 2] = 0.0f;
            As[r][c + 3] = 0.0f;
        }
    }
    const bool b_vec_ok = ((cols & 3) == 0);
    for (int idx = tid; idx < B_VECS; idx += nthreads) {
        const int r = idx / B_VECS_PER_ROW;
        const int c = (idx % B_VECS_PER_ROW) * 4;
        const int gc = block_col + c;
        if (b_vec_ok && gc < cols) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
            __pipeline_memcpy_async(&Bs[r][c], B + r * cols + gc, sizeof(float4));
#else
            const float4 v = *reinterpret_cast<const float4*>(B + r * cols + gc);
            Bs[r][c + 0] = v.x;
            Bs[r][c + 1] = v.y;
            Bs[r][c + 2] = v.z;
            Bs[r][c + 3] = v.w;
#endif
        } else {
            #pragma unroll
            for (int u = 0; u < 4; ++u) {
                const int gcc = gc + u;
                Bs[r][c + u] = (gcc < cols) ? B[r * cols + gcc] : 0.0f;
            }
        }
    }
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    __pipeline_commit();
    __pipeline_wait_prior(0);
#endif
    __syncthreads();
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    const int local_row = ty * TM;
    const int local_col = tx * TN;
    #pragma unroll
    for (int k = 0; k < TK; ++k) {
        float a_frag[TM];
        float b_frag[TN];
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            a_frag[i] = As[local_row + i][k];
        }
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            b_frag[j] = Bs[k][local_col + j];
        }
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                acc[i][j] = fmaf(a_frag[i], b_frag[j], acc[i][j]);
            }
        }
    }
    // Vectorized stores: each thread owns TN=4 contiguous columns.
    const bool c_vec_ok = ((cols & 3) == 0);
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int gr = block_row + local_row + i;
        if (gr < rows) {
            const int gc0 = block_col + local_col;
            if (c_vec_ok && gc0 < cols) {
                float4 v;
                v.x = acc[i][0];
                v.y = acc[i][1];
                v.z = acc[i][2];
                v.w = acc[i][3];
                asm volatile("st.global.cs.v4.f32 [%0], {%1,%2,%3,%4};" :: "l"(reinterpret_cast<unsigned long long>(C + gr * cols + gc0)), "f"(v.x), "f"(v.y), "f"(v.z), "f"(v.w) : "memory");
            } else {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    const int gc = gc0 + j;
                    if (gc < cols) {
                        C[gr * cols + gc] = acc[i][j];
                    }
                }
            }
        }
    }
}

}  // namespace

torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 && B.scalar_type() == torch::kFloat32,
                "A and B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.size(1) == TK, "This custom kernel is specialized for inner dimension K=32");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();

    const int64_t rows = A_c.size(0);
    const int64_t cols = B_c.size(1);

    auto C = torch::empty({rows, cols}, A_c.options());
    if (rows == 0 || cols == 0) {
        return C;
    }

    dim3 block(BN / TN, BM / TM);  // 16 x 32 threads
    dim3 grid(
        static_cast<unsigned int>((cols + BN - 1) / BN),
        static_cast<unsigned int>((rows + BM - 1) / BM)
    );

    auto stream = at::cuda::getCurrentCUDAStream();
    matmul_m32768_k32_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>(),
        static_cast<int>(rows),
        static_cast<int>(cols)
    );

    return C;
}
"""

_cpp_src = "torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B);"

_matmul_ext = load_inline(
    name="matmul_m32768_k32_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom CUDA implementation for:
        A: (M, 32), B: (32, M)  ->  C: (M, M)
    where M is large and the inner dimension is very small.
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        if A.is_cuda and B.is_cuda:
            return _matmul_ext.matmul_forward(A, B)

        # Preserve the input device while still performing the matmul itself on CUDA.
        out_device = A.device
        A_gpu = A.to(device="cuda", dtype=torch.float32).contiguous()
        B_gpu = B.to(device="cuda", dtype=torch.float32).contiguous()
        C_gpu = _matmul_ext.matmul_forward(A_gpu, B_gpu)
        return C_gpu.to(out_device)

